import SuperJSON from './dist/index.js';
import assert from 'node:assert/strict';
const s = new SuperJSON({errorStack: {mode: 'frames'}});
s.allowErrorProps('stackFrames');
const e = new Error('oops');
e.stack = 'Error: oops\n    at /tmp/example.js:1:2';
const p = s.serialize(e);
assert.equal(p.meta.values[0], 'Error/frames');
assert.deepEqual(p.json.stackFrames, [{raw: 'Error: oops'}, {raw: 'at /tmp/example.js:1:2'}]);
